-- GENERATED by `wfj generate` from data/quest/quest-0004.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [4021] = { "Contrattacco!", "Porta un ⟦Piece of Krom'zar's Banner=Pezzo dello Stendardo di Krom'zar⟧ a Regthar Deathgate, a ovest del ⟦Crossroads=Crocevia⟧.", "L'⟦Horde=Orda⟧ loda i tuoi successi contro i Kolkar, ma i Kolkar sono furiosi. Mi riferiscono che un contingente di Kolkar è giunto nelle ⟦Barrens=Savane⟧ dalla loro terra, ⟦Desolace=Desolanda⟧, in cerca di vendetta. Secondo l'ultimo rapporto, proprio ora stanno avanzando contro questi bunker, da ovest!\n\nAffronta gli invasori Kolkar e poni fine alla loro minaccia nelle ⟦Barrens=Savane⟧. Uccidili finché non comparirà il loro capo, il signore della guerra Krom'zar. Sconfiggilo e portami un pezzo del suo stendardo come prova.\n\nContiamo su di te, {name}.", "Hai lo stendardo?", "Ce l'hai fatta! Hai sconfitto i Kolkar!\n\nMi assicurerò che Thrall venga a sapere delle tue imprese qui, {name}.\n\nA testa alta. Fai onore a te stess<o/a> e all'⟦Horde=Orda⟧.", 0xa53d08ff, 0x6d88481e, 0xa8ad7e6b, 0x38ed797c, 0x77820849, "....." },
  [4124] = { "Il corriere scomparso", "Parla con Ginro Hearthkindle a Feathermoon Stronghold.", "Un mio collaboratore, Ginro Hearthkindle, cerca aiuto per ritrovare un corriere e i pacchi che trasportava. È passata una settimana o giù di lì da quando il corriere è scomparso; le nostre ricerche non hanno dato frutti, e siamo a un punto morto. Purtroppo ho dovuto dichiarare il corriere disperso in missione.\n\nSe hai tempo e mezzi da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui nella roccaforte, forse nei suoi alloggi.", nil, "Ti manda Latro, immagino. Anche se a questo punto credo sia una causa persa, accetterò qualsiasi aiuto tu possa offrirmi. Devo ammetterlo... sarò felice quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno senza nulla da mostrare per i miei sforzi, a parte denti di gnoll e delusione.", 0x05891b2b, 0xd64f6ee6, 0x6914d46a, nil, 0xadd3e8c1, "...m." },
  [4125] = { "Il corriere scomparso", "Trova la barca del corriere da qualche parte lungo la costa di Feralas.", "È passata circa una settimana da quando Raschal, il corriere, è partito per Thalanaar. Conosce bene Feralas; è con noi da quando la generale Feathermoon ha guidato qui le forze di spedizione. So che il suo piano era prendere una barca a remi lungo la costa e cercare di attraversare il sud di Feralas per evitare l'accampamento dell'⟦Horde=Orda⟧.\n\nIo non sono riuscito a trovare la sua barca, ma forse tu ci riuscirai. Forse è nascosta, o forse è stata affondata. In ogni caso, potrebbe contenere un indizio su dove si trovi. Se scopri qualcosa, ti prego, fammelo sapere.", nil, "Hai trovato quella che sembra una barca a remi distrutta. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano il lato di babordo; la barca è ridotta quasi alla sua semplice ossatura di legno. Qualunque cosa l'abbia distrutta, probabilmente ha cercato di spezzarla in due. Sul lato di tribordo è dipinto un piccolo stemma di Feathermoon Stronghold.\n\nNel fango alla base della barca, un luccichio metallico attira la tua attenzione...", 0x05891b2b, 0xbe904bf7, 0x2af52f5d, nil, 0x30d69719, "...m." },
  [4127] = { "Il relitto della barca", "Torna a Feathermoon Stronghold e mostra a Ginro Hearthkindle il ⟦Discarded Knife=Coltello Scartato⟧ che hai trovato.", "Passando la mano nel fango, le tue dita sfiorano il manico di un coltello. Sembra ben tenuto, e si potrebbe supporre che chiunque fosse sulla barca l'abbia perso. Forse il grosso pezzo mancante della barca ha qualcosa a che fare con la perdita.\n\nPrendi il coltello, ricordando che Ginro Hearthkindle, a Feathermoon Stronghold, ti ha chiesto di tornare da lui con qualsiasi indizio trovato. Hai però la sensazione di non essere del tutto sol<o/a> nell'acqua...", "Ah, bentornat<o/a>, {name}. Spero che tu sia riuscit<o/a> a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.", "Interessante... Credo che questo sia il coltello di Raschal. Dici di averlo trovato sul fondo, insieme alla sua barca? Be', il solo ritrovamento del coltello potrebbe non bastare a collegarlo alla scomparsa di Raschal; abbiamo però un'opzione insolita per cercare di saperne di più.\n\nHai mai sentito parlare di psicometria?", 0x7d02beea, 0x85c0f895, 0x3c45061d, 0xbc63d551, 0xd54492e1, "....." },
  [4129] = { "Il coltello svelato", "Porta il ⟦Discarded Knife=Coltello Scartato⟧ a Quintis Jonespyre, a Feathermoon Stronghold.", "Il druido residente della roccaforte, Quintis Jonespyre, ha alcune capacità... insolite. Una di queste è la psicometria: la capacità di rivelare la storia di un oggetto toccandolo. Non chiedermi come faccia; per me è magia che non capisco e che preferisco non capire. So però due cose: uno, l'ho vista funzionare, e due, quello scansafatiche è in debito con me.\n\nPorta il coltello a Quint, su nella sua casetta sull'albero, e digli da parte mia che il suo debito al Kalimdor Hold 'Em sarà saldato se fa le sue magie su quel coltello.", "Ti manda Ginro, eh?\n\nLe mie letture psicometriche sono piuttosto spossanti per la mente... ma lo sono anche le mie perdite al Kalimdor Hold 'Em. Qui alla roccaforte mi chiamano \"il Re delle Batoste\". Sfortunato a carte... fortunato nel padroneggiare i segreti della natura, immagino.\n\nComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Se mi passi il coltello, possiamo cominciare.", "Grazie, {name}.\n\nLa psicometria non è certo un'arte esatta, ma in passato l'ho usata per far luce su situazioni che altri avevano dato per perse. Credo che usarla sul coltello che hai trovato ci darà un'idea di cosa è successo a Raschal.\n\nCi vorrà solo un momento, ma non è quello che definirei un compito facile per chi lancia incantesimi. Abbi pazienza.", 0x5a2b17b8, 0x98645dbc, 0x01a82e3d, 0xea41a841, 0x24cb6162, "....." },
  [4130] = { "Lettura psicometrica", "Parla con Ginro Hearthkindle a Feathermoon Stronghold.", "Mi gira ancora un po' la testa, scusa. Comunque, ho avuto alcune visioni utili.\n\nRaschal prende due grandi zaini di cuoio dalla sua barca e si addentra verso l'interno; poi però torna alla barca. Vedo scalpi di gnoll... si è imbattuto in alcuni gnoll, Raspalegno, credo che si chiamino. È molto preoccupato, quasi terrorizzato, per qualcosa. Tanto che non si accorge degli elementali dell'acqua che si formano alle sue spalle. Le immagini... si fermano qui.\n\nDevo riposare, scusa {name}. Racconta a Gin quello che ho visto. Deve saperlo.", nil, "Grazie per avermi riferito le visioni di Quint, {name}. Cercherò di ricordarmi di essere un po' più indulgente con lui la prossima volta che giochiamo a carte.\n\nRaschal sa difendersi in uno scontro, e gli gnoll non sono certo qualcosa che lo farebbe preoccupare, figuriamoci terrorizzare. Comunque, forse tu e i tuoi potete agire in base a queste nuove informazioni e ottenere la svolta di cui abbiamo disperatamente bisogno.", 0xf6ce658b, 0xd64f6ee6, 0x74d0882e, nil, 0x42b23019, "...m." },
  [4131] = { "Gli gnoll Raspalegno", "Cerca negli accampamenti degli gnoll Raspalegno, nel sud di Feralas, tracce degli effetti personali del corriere o del corriere stesso.", "I nostri \"amici\" Raspalegno potrebbero aver fatto fuori Raschal, alla fine, ma qualcosa mi dice che non è andata così. Comunque, sono il posto migliore da cui cominciare a cercare.\n\nVorrei avere un'idea più chiara di cosa fare, ma per ora tutto ciò che ho è: 'Cerca negli accampamenti dei Raspalegno, vai.' So però che gli gnoll tengono gli oggetti che razziano e se li contendono; forse si sono imbattuti negli zaini di cui parlava Quint. Nelle ricerche passate non avevo rischiato uno scontro frontale, ma con la visione di Quint, io dico: falli a pezzi.", nil, "Appesi a un albero lì vicino ci sono due grandi zaini di cuoio. Ognuno porta sul davanti una piccola insegna di Feathermoon Stronghold...", 0xb9f65bac, 0x9cdc696a, 0x64b79ecf, nil, 0xed276df7, "...m." },
  [4135] = { "La ⟦The Writhing Deep=Fossa Fremente⟧", "Ora che hai scoperto dove Raschal è stato visto l'ultima volta, continua a cercare lui o i suoi resti nella Fossa Fremente. Secondo il biglietto, si trova a sud degli accampamenti degli gnoll Raspalegno.", "Negli zaini ci sono due cose: la prima è un pacco di merci destinato a Thalanaar, la seconda un biglietto scritto in fretta a un lettore sconosciuto.\n\nIl biglietto parla della scoperta di insidiose creature simili a insetti a sud degli accampamenti degli gnoll, in un luogo chiamato Fossa Fremente. L'autore sentiva il bisogno di indagare di persona, come se fosse una grave minaccia per tutta Feralas. Il biglietto è firmato: \"Raschal di Feathermoon\".\n\nSembra che tu abbia trovato il luogo dove è finito Raschal.", nil, "Hai scoperto un grosso baccello di natura aliena. La superficie del baccello sembra mucosa, anche se qua e là spuntano protuberanze indurite. Il baccello è alto e largo abbastanza da contenere facilmente un umanoide... e dalla debole sagoma umanoide visibile attraverso la sua pelle, deduci che è proprio ciò che racchiude.", 0x7b083e72, 0xaa66fc0f, 0xc369aa3c, nil, 0x656d0a45, "...m." },
  [4161] = { "La ricetta dei kaldorei", "Raccogli 7 Piccola Zampa di Ragno per Zarrin a Dolanaar.", "Tanto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino di {class}, {name}, quindi ascolta bene ciò che ho da dirti.\n\nI kaldorei sono sempre stati molto orgogliosi del loro rapporto armonioso con la natura. Questo significa che prendiamo dalla natura solo ciò che è necessario, e che restituiamo in egual misura. Questo equilibrio ci ha dato molto, {name}.\n\nVa' e raccogli sette zampe di ragno piccolo, non una di più, e torna da me.", "Ricorda l'equilibrio, {name}. Voglio che tu sviluppi una comprensione e una forte empatia per le foreste viventi.", "Ricorda sempre ciò che ti ho mostrato oggi, {name}. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche nei tempi difficili.", 0xc790841a, 0x7c7f5405, 0x2a2ed2f9, 0xb7a98f7e, 0xbe9fad73, "....." },
  [4181] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧", "Se vuoi saperne di più sull'⟦Goblin Engineering=Ingegneria dei Goblin⟧, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "L'ingegneria di livello esperto si divide in due discipline distinte: quella degli gnomi e quella dei goblin. Ti parlo dell'Ingegneria dei Goblin solo perché sono un istruttore onesto. Ai goblin piace costruire cose che esplodono, e raramente si curano di ciò che sta in mezzo... nemmeno di se stessi.\n\n{name}, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Le reclute fresche le fiuto come fiuto un'ottima polvere esplosiva: a un miglio di distanza. Sei venut<o/a> per imparare a padroneggiare l'esplosione?", "Be', {name}, hai fatto bene a cercare la mia guida! Qualsiasi sprovveduto può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa radioattiva, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧ ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie dritte, {name}, e forse imparerai qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [4265] = { "Liberato dall'alveare", "Libera Raschal dall'alveare degli Zukk'ash.\n\nTorna da Ginro Hearthkindle a Feathermoon Stronghold e digli che Raschal è vivo e sta bene.", "Quando lo tocchi, il baccello si apre un poco e rivela un elfo della notte, sorprendentemente ancora vivo. Sembra in buona salute, anche se profondamente stordito. Mentre lo aiuti a scendere dal baccello, si rianima.\n\n\"Grazie a Elune, mi hai salvato, amico! Io... io sono Raschal, e mi sono risvegliato paralizzato dentro questo baccello dopo che questi insetti mi hanno sopraffatto. Ti ha mandato la roccaforte?\"\n\nSembra che tu abbia trovato il corriere scomparso!", "Hai qualcosa da riferire, {name}?", "Bentornat<o/a> a casa, {name}. Raschal si è presentato poco fa e mi ha raccontato cos'è successo.\n\nIo... no, l'intera roccaforte non sa nemmeno come cominciare a ringraziarti per la tua grande impresa; Raschal sarebbe morto senza il tuo aiuto tempestivo, e ce lo hai dato senza nemmeno un accenno a un compenso da mercenario. Porti il segno di <un/una> ver<o/a> eroe. Sappi che in Ginro Hearthkindle avrai sempre un amico.", 0xe090d26e, 0xc1b8edb5, 0x3c699a4e, 0x2ff3a2d1, 0x73a57ae8, "....." },
  [4266] = { "Accoglienza da eroe", "Parla con Shandris Feathermoon a Feathermoon Stronghold.", "{name}, la generale Shandris Feathermoon vorrebbe parlarti di persona. Senza dubbio vuole ringraziarti per il servizio reso alla roccaforte, ma so che vuole anche parlarti delle creature insettoidi che tu e Raschal avete affrontato nel sud di Feralas. I rapporti su quegli insetti Zukk'ash sono... a dir poco spaventosi.\n\nLa generale Feathermoon ti aspetta nell'edificio principale.", nil, "{name}, ti ringrazio di cuore per l'aiuto che ci hai dato. Il tuo coraggio di fronte a forze soverchianti meriterebbe una ricompensa mille volte più grande. Tuttavia, spero che accetterai questa a nome dell'intera roccaforte.\n\nOra, se permetti... vorrei chiedere il tuo aiuto ancora una volta. Alla luce della scoperta dell'alveare degli Zukk'ash qui a Feralas, credo che tu sia la scelta migliore per questa missione.", 0xfc173165, 0x7bd0a992, 0xf15db714, nil, 0x846faacd, "...m." },
  [4267] = { "L'ascesa dei silitidi", "Porta il ⟦Raschal's Report=Rapporto di Raschal⟧ a Gracina Spiritmight a Darnassus.", "Ti affido una copia del rapporto che Raschal ha redatto sull'infestazione del sud-est di Feralas. Mentre il rapporto principale viene archiviato a Darnassus, voglio che tu consegni questa copia a una collaboratrice del Protectorate. Si chiama Gracina Spiritmight; è una sacerdotessa che risiede nel ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus. Conosce bene questo genere di creature, e se ricevesse questo rapporto ne trarremmo tutti beneficio.\n\nPuoi andare. Buona fortuna, {name}; che Elune vegli su tutti noi.", "Benvenut<o/a> in questo tempio benedetto, amico. Il tuo arrivo da Feathermoon Stronghold mi era stato predetto. Hai il rapporto che Shandris Feathermoon ti ha chiesto di portare?", "Noi elfi della notte conosciamo il terrore descritto in questo rapporto. Shandris ha fatto bene a mandare da me questo rapporto, e te.\n\nQueste creature divoreranno Feralas in fretta; sono a dir poco una delle peggiori minacce che dovremo mai affrontare. Gli insetti che tu e il corriere avete incontrato sono noti come silitidi. Sono semplici strumenti di una delle più grandi minacce che l'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ dovranno mai affrontare.\n\nPrego che avremo la risolutezza di sconfiggerli prima che ci distruggano.", 0x50a8e84e, 0x39f5732a, 0xda5712a8, 0x26cf8b80, 0x993d1f4d, "....." },
  [4281] = { "Una consegna per Thalanaar", "Porta l'Undelivered Parcel a Falfindel Waywarder, a Thalanaar.", "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Raspalegno doveva essere consegnato alla piccola stazione di posta di Thalanaar, nel sud-est di Feralas. Qualunque sia stata la sorte del corriere scomparso, il compito di consegnare il pacco resta incompiuto.\n\nEsaminando il pacco con attenzione, noti un nome scritto a mano sulla confezione: \"Falfindel Waywarder\". Forse è lui il destinatario finale del pacco.", "Benvenut<o/a> a Thalanaar, {class}. Ti serve aiuto di qualche tipo?", "Sia lodata Elune, la consegna da Feathermoon Stronghold è finalmente arrivata!\n\nLa tua presenza qui mi fa pensare che forse a Raschal, il nostro solito corriere, sia capitata una brutta sorte. Spero che tutto si risolva. So che di recente i Raspalegno sono diventati molto agitati per qualcosa che arriva da sud. Forse è caduto vittima delle terre selvagge laggiù; fa' attenzione, amico.\n\nIn ogni caso, grazie ancora. Ecco il compenso per la consegna di questo pacco.", 0x86751311, 0x715b3184, 0x7c56c873, 0xc22061a9, 0x3e39cede, "....." },
  [4295] = { "La birra di Rocknot", nil, nil, "Oh, birra! Ucciderei per un po' di birra dei ⟦Dark Iron=Ferroscuro⟧!! Presto, sto tornando sobrio! Lo so perché la sobrietà mi annebbia la vista... e ti fa somigliare a <un/una> {race} che ho fatto fuori la settimana scorsa!", "Cos'è questo? Ah! Ha l'odore della birra dei ⟦Dark Iron=Ferroscuro⟧! L'alcol mi ha annebbiato la vista, ma capisco che tu, <signore/signora>, sei <un/una> <vero/vera> <amico/amica>!", 0x086856d2, nil, nil, 0xa2c71db2, 0x0d80f610, ".mm..", nil, nil, nil, nil, 0xb3506339 },
  [4296] = { "La Tavoletta dei Sette", "Porta la ⟦Tablet Transcript=Trascrizione della Tavoletta⟧ a Maxwort Uberglint, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Sono venuto nelle ⟦Burning Steppes=Steppe Ardenti⟧ seguendo le leggende dei Sette. Erano nani di grande sapere e potere, e se hai sapere e potere, la ricchezza arriva di sicuro.\n\nÈ questo che voglio. La ricchezza!\n\nSe riusciamo a scoprire di più sui Sette, forse possiamo arricchirci insieme. Si dice che le Rovine di Thaurissan custodiscano la Tavoletta dei Sette, che racchiude il sapere degli antichi nani. Trova la tavoletta, copiane il testo e portamelo. Scopriamo insieme i suoi segreti!", "Hai gli scritti dei Sette, {name}? Hai scoperto i segreti della loro tavoletta?", "Ah, hai trovato la tavoletta! E la tua trascrizione è eccellente! Sei sicur<o/a> di essere <un/una> {class} e non uno scriba?\n\nEcco a te, {name}. Ecco il pagamento che ti avevo promesso.", 0x863c0b42, 0xc0b00f60, 0x910aab7a, 0x793ccb86, 0xfcd7e593, "....." },
  [4297] = { "Pappa per il piccolo", "Porta 5 Costato di Inseguitore Peloargento ad Agnar Beastamer, nelle Entroterre.", "I draghi fatati sono onnivori: vuol dire che mangiano sia carne sia vegetali. Se quest'uovo deve schiudersi, è meglio farci trovare pronti. Un buon pasto per questi piccoletti sono i costati di carne, crudi e succosi, che tu ci creda o no. Non sono mai riuscito a scoprire perché, ma ha qualcosa a che fare con i piani di Elune per gli elfi... forse dovevano esserne i protettori o qualcosa del genere, che ne so.\n\nPer ora all'uovo ci penso io; perché non mi procuri dei bei costati di inseguitore Peloargento da fargli mangiare quando si sarà schiuso?", "Trovata la carne, {name}? Il tuo uovo qui è quasi pronto a schiudersi. Se il piccolo non fa un primo pasto come si deve, potrebbe non superare la prima settimana, e mi dispiacerebbe davvero.\n\nNon posso mentirti, {name}. Ti invidio per aver avuto quest'uovo. Non farmi pentire di averti dato una mano così.", "Questi andranno benissimo e, se non sbaglio, il tuo uovo è quasi pronto a schiudersi. Che effetto fa? Sai, stai per diventare <padre/madre>! Ah ah, non pensavi di doverti prendere una responsabilità simile, eh?", 0xccaca750, 0xe072dedf, 0xc37f8279, 0x2f58b6a1, 0xcba4d08b, ".....", nil, nil, nil, nil, 0x797e01c8 },
  [4298] = { "Diventare genitore", "Parla con Agnar Beastamer nelle Entroterre.", "Accidenti, era molto più pronto di quanto pensassi...", nil, "Ecco, prendi l'uovo... meglio che ce l'abbia tu, così si lega a te e ti considera <il/la> sua <papà/mamma>.\n\nCongratulazioni, {name}. Sei diventat<o/a> genitore... più o meno.", 0xd65f6783, 0xc7b43955, 0x0bc0ac2d, nil, 0xcca17ed2, "...m.", nil, nil, nil, nil, 0x08e439a2 },
  [4402] = { "Lo ⟦Cactus Apple Surprise=Sformato di Mele di Cactus⟧ di Galgar", "Porta a Galgar 10 Mela di Cactus. Ricordi che ha detto che si trovano vicino ai cactus.", "Fa proprio caldo qui nella ⟦Valley of Trials=Valle delle Sfide⟧.\n\n<Galgar si asciuga la fronte.>\n\nSe solo avessi qualche mela di cactus, potrei preparare il mio famoso sformato di mele di cactus! Niente ti rinfresca più in fretta di un pezzo di quella delizia.\n\nFacciamo così, {name}. Se mi porti 10 mele di cactus, ti preparerò qualche porzione di sformato di mele di cactus da portare nelle tue avventure, e in più un manuale di addestramento gratis. Se ti interessa, trovi le mele di cactus vicino alle piante di cactus qui intorno.", "Hai finito di raccogliere le mele di cactus?", "Magnifico, {name}! Come promesso, ecco il tuo sformato di mele di cactus. Scegli anche uno di questi manuali di addestramento. Ne ho in abbondanza per tutti.", 0xaed68386, 0x6d1de7e5, 0x567922ac, 0x15808a02, 0x967033b1, "....." },
  [4449] = { "In trappola!", "Uccidi 8 Dark Iron Geologist e porta 15 pezzi di ⟦Silk Cloth=Tessuto di Seta⟧ alla persona chiusa nel gabinetto nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Ehi! Ehi, tu! Vieni qua!\n\nDevi darmi una mano. Scappavo da quei nani ⟦Dark Iron=Ferroscuro⟧ e mi sono nascosto qui dentro per non farmi vedere. Maledetti geologi bastardi e le loro arti magiche! Devono avermi visto nascondermi, perché un attimo dopo hanno chiuso la porta e mi hanno lasciato qui dentro.\n\nDai una lezione a quei geologi! Oh... e mi procureresti qualche pezzo di tessuto di seta per... per... niente.", "Non ho tutto il giorno! Portami quei pezzi di tessuto di seta! Cioè, i geologi. Prendi quei geologi! Si meritano di sentire la mia... beh... la tua ira.", "Oh, fantastico! E pure morbido al tatto!\n\nCosa? Ah, già... i geologi. Gliele hai suonate, eh? Non so come ringraziarti, {name}. Così avrò un po' di tempo per finire qui dentro... Grazie ancora, {name}.", 0xab9278e3, 0xc0a43cff, 0xc422c491, 0x13a88031, 0x98779dfb, "....." },
  [4450] = { "Il registro da Tanaris", "Prendi la copia del Libro Mastro di Ferrofiz, poi trova gli oggetti elencati prima di andare da Krinkle Goodsteel a Tanaris.", "Ah, sai che c'è? Questo mi fa venire in mente una cosa.\n\nTi va di finire un lavoretto che avevo preso quando ero a Tanaris? È facile...\n\nKrinkle Goodsteel, a ⟦Gadgetzan=Meccania⟧, cercava della roba che si trova qui nella ⟦Searing Gorge=Gorgia Rovente⟧ e in qualche altro posto. Magari potresti dare un'occhiata alla lista e poi portargli tutto?\n\nSe ti interessa, ti faccio scivolare il suo registro sotto la porta. Prendilo e, quando avrai raccolto tutto, riportagli la roba che vuole.", "Sì, sì? Cosa posso fare per te, {race}? Sono molto occupato e ho tanti clienti che chiedono i miei servigi. Magari puoi sbrigarti. Non voglio essere scortese, ma non ho proprio tempo se devo mettermi in pari con tutto il lavoro.", "Oh, ti sei degnat<o/a> di fare un po' del lavoro che avevo chiesto. Eccellente. E io che pensavo che volessi chiedermi di fabbricarti qualcosa.\n\nSono tutti perfetti... e c'è tutto. Grazie, {class}.\n\nForse non guasterebbe darti una piccola ricompensa... mmh, cosa potrebbe esserti utile.", 0xfa56f393, 0xfbaa0d2b, 0xccb4891c, 0x920e8057, 0x3d8ac6bb, "....." },
  [4451] = { "La chiave della libertà", "Esplora la ⟦Searing Gorge=Gorgia Rovente⟧ e trova un uso per la Grimesilt Outhouse Key che hai trovato.", "La piccola chiave d'ottone sembra piuttosto semplice... L'unica cosa che la distingue sono alcune parole incise sulla testa:\n\n\"Latrina dei ⟦Dark Iron=Ferroscuro⟧ - Non duplicare.\"\n\nNon hai idea di che cosa significhi né di dove possa portarti.", "*coff coff*\n\nChi è? Non vedi che sono occupato?", "Ma guarda un po'! Come diavolo hai fatto?! Hai trovato la chiave! Lo sapevo che quei maledetti Ferroscuro la nascondevano, dopo avermi chiuso qua dentro! Grazie mille, {name}. Sei <il/la> migliore! Adesso gira la chiave e fai uscire il vecchio Locheed!", 0x1d423cb0, 0xdf1d614f, 0xe0aab529, 0xd1c3c55d, 0x30438394, "....." },
  [4485] = { "Il Tome of Nobility", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Salve, {name}. Vedo che la tua dedizione resta salda, come la tua fede.\n\nCredo sia giunto il momento che tu parli con Duthorian Rall a ⟦Stormwind=Roccavento⟧. Ci sono altre lezioni che devi imparare, e sento che sei <pronto/pronta>.\n\nCercalo nella ⟦Cathedral of Light=Cattedrale della Luce⟧ e, {name}, prendi sul serio queste lezioni. Hai raggiunto la tua posizione con umiltà e duro lavoro: non deluderci diventando arrogante.\n\nStammi bene.", nil, "Ah, sei tornat<o/a> alla Cattedrale, {name}. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai <degno/degna>.\n\nCi sono in giro molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.", 0x2923ea98, 0x0f3ca705, 0x454c6c6f, nil, 0x47e1bbd2, "...m." },
  [4486] = { "Il Tome of Nobility", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Bene, bene, bene, guarda <il/la> possente paladin<o/a> in tutta la sua regalità.\n\nScusa, {name}, non volevo offenderti... è che a volte divento un po' geloso quando vedo alcune delle imprese che hai compiuto. Tiza dice che è il mio punto debole, e le ho giurato che ci avrei lavorato su. Solo che a volte è dura, capisci?\n\nMa il motivo per cui volevo parlarti è che Duthorian Rall, a ⟦Stormwind=Roccavento⟧, ha fatto sapere che ti aspetta nella ⟦Cathedral of Light=Cattedrale della Luce⟧ quando sarai <pronto/pronta>. Sembrava importante. Sembrava che stesse succedendo qualcosa.", nil, "Ah, sei tornat<o/a> alla Cattedrale, {name}. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai <degno/degna>.\n\nCi sono in giro molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.", 0x2923ea98, 0x0f3ca705, 0x3240aaf3, nil, 0x47e1bbd2, "...m.", nil, nil, 0x381e65db, nil, nil },
  [4487] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Ah, bene, sei qui. Ti avevo mandato dietro <una/un> <succube/infernale> per attirare la tua attenzione, ma a quanto pare sei arrivat<o/a> prima che ti trovasse. Poco importa.\n\nUltimamente si parla del tuo potere crescente: un bene per te, forse un male per altri. Ma sono dettagli irrilevanti. Il punto è che credo tu abbia dato prova di te, e quindi meriti... eh eh... una sorta di benedizione.\n\nSopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧, troverai un uomo di nome Strahad. Credo che le vostre strade si siano già incrociate.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0xf53d45e1, nil, 0x23773eba, "...m.", nil, nil, 0xe53a38b3, nil, nil },
  [4488] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Ah, {name}, ti sei degnat<o/a> di onorarci della tua presenza. Che meraviglia!\n\nSpero che tu non ti aspetti anche di essere servit<o/a> e riverit<o/a>. Il tuo potere cresce in fretta, ma quanto a vera conoscenza e comprensione sei ancora un cucciolo. Se non stai attent<o/a>, la corruzione travolgerà te e la tua debole volontà.\n\nMa vengo al punto: Strahad vuole parlarti. Risiede ancora nella sua torre che domina ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Ti consiglio di non metterci troppo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0x22753d85, nil, 0x23773eba, "...m." },
  [4489] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Tu, {race}! Vieni qui!\n\nSei tu <quello/quella> che chiamano {name}, vero?\n\nLo immaginavo. Sarò breve: il tuo potere sta crescendo, e la cosa non è passata inosservata. E ora è giunto il momento che i tuoi sforzi siano ricompensati.\n\nVa' nelle ⟦Barrens=Savane⟧. Lì, sopra ⟦Ratchet=Porto Paranco⟧, troverai Strahad Farsan: forse ti ricordi di lui? Vuole scambiare due parole con te. Io non perderei tempo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0x9e1f9f00, nil, 0x23773eba, "...m." },
  [4490] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧ per imparare a evocare un vildestriero.", "Vorrei darti una ricompensa per la tua pazienza e il tuo duro lavoro. Ma sappi questo: in futuro il potere di evocare un vildestriero sarà molto più difficile da ottenere. Dovrai guadagnartelo... e non sarà facile.\n\nPer ora, va' con il potere di evocare una simile creatura e usalo come meglio credi.", nil, "Buona fortuna, {name}. Non vedo l'ora di rivederti in futuro.", 0x5220fbc8, 0x7950b530, 0x285bb1cf, nil, 0x2dc44b87, "...m." },
  [4495] = { "Un buon amico", "Trova Iverron presso la caverna a nord.", "Un mio amico di nome Iverron di solito viene a trovarmi ogni giorno alla stessa ora. La cosa strana è che oggi non si è proprio visto: anzi, è in ritardo di parecchie ore.\n\nLo ammetto, sono un po' preoccupata, {name}. Iverron passa molto tempo vicino alla caverna a nord, e sono sicura che sai quanto sia pericolosa: ragni, ovunque!\n\nSe per caso vai da quelle parti, però, potresti tenere gli occhi aperti?", nil, "Sono così felice che tu mi abbia trovato, {name}. Come sapevi che ero qui?", 0xc68e1991, 0xa973ef17, 0xfa034016, nil, 0x8083d57b, "...m." },
  [4542] = { "Messaggio per il ⟦Freewind Post=Presidio di Ventolibero⟧", "Porta il ⟦Urgent Message=Messaggio Urgente⟧ al guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧.", "<Viaggiatore/Viaggiatrice> <coraggioso/coraggiosa>, i centauri hanno intensificato i loro attacchi in questa zona. Il ⟦Freewind Post=Presidio di Ventolibero⟧ deve sapere subito di queste nuove scorrerie! Cerca il guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧, a sud-est, e consegnagli questo messaggio urgente.\n\nE sta' <attento/attenta>: evita il clan dei ⟦Grimtotem=Totem Truce⟧ qui vicino... ultimamente si comportano in modo strano con noi.", "Che cosa vuoi, {class}? Un messaggio urgente... per me?", "Altre cattive notizie! Questi centauri hanno passato il limite! Hanno assalito una delle mie carovane di rifornimenti e massacrato tutto il gruppo. È un oltraggio, e non resterà impunito!", 0xc0420527, 0xf4ee9842, 0x3bc2e3b4, 0x48656749, 0x3b14844c, "....." },
  [4581] = { nil, "Porta il ⟦Shindrell's Note=Messaggio di Shindrell⟧ a Kayneth Stillwind a ⟦Forest Song=Cantaselva⟧.", "Il druido Kayneth Stillwind mi ha mandato un messaggio. Vorrebbe un rapporto su ciò che accade lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia diffondendo per ⟦Ashenvale=Valtetra⟧... e forse ha ragione.\n\nEcco, portagli il mio rapporto. Lo troverai nel santuario di ⟦Forest Song=Cantaselva⟧, nei ⟦Nightsong Woods=Boschi del Canto Notturno⟧, a est.", "Hai qualcosa per me?", "Ah, il rapporto di Shindrell! Mille grazie, {name}. Shindrell è una brava sentinella, coraggiosa e acuta. Devo leggerlo per cercare indizi di una malvagità che temo si stia diffondendo per ⟦Ashenvale=Valtetra⟧.", 0x9dc5369f, 0x412eac24, 0x2655e857, 0x38f32e8a, 0x7f079b03, "e...." },
  [4601] = { "La Lavatutto 5200!", "Inserisci un Grime-Encrusted Item nella Lavatutto 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «La Lavatutto 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? La Lavatutto 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi alla Lavatutto 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nella Lavatutto 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4602] = { "La Lavatutto 5200!", "Inserisci un Grime-Encrusted Item nella Lavatutto 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «La Lavatutto 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? La Lavatutto 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi alla Lavatutto 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nella Lavatutto 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4605] = { "La Lavatutto 5200!", nil, nil, nil, "Così come era partita, la Lavatutto 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro la Lavatutto 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4606] = { "La Lavatutto 5200!", nil, nil, nil, "Così come era partita, la Lavatutto 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro la Lavatutto 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4641] = { "Il tuo posto nel mondo", "Parla con Gornek. Ricordi che Kaltunk ha segnato sulla tua mappa dove si trova e ti ha detto che Gornek risiede nell'Antro del Tirocinio, un edificio a ovest.", "Finalmente hai l'età giusta, {name}... l'età per combattere nel nome dell'⟦Horde=Orda⟧. Per conquistare per la gloria del Capoguerra.\n\nSì...\n\n<Kaltunk ti squadra.>\n\nAndrai benissimo.\n\nSenza dubbio vorresti trovare un grande drago o un demone e strangolarlo a mani nude, ma forse sarebbe saggio cominciare con qualcosa di meno... pericoloso.\n\n<Kaltunk ride.>\n\nPresentati a Gornek: dovrebbe poterti affidare un compito più adatto a <un/una> giovane {class}. Troverai Gornek nell'Antro del Tirocinio, a ovest.", nil, "Un'altra recluta di Kaltunk, eh?\n\nSiamo messi proprio male se questo è il meglio che l'⟦Horde=Orda⟧ sa produrre. Non importa. Quando penseremo che sei pront<o/a> a lasciare la Valle, sarai <un/una> <fiero/fiera> <guerriero/guerriera> dell'⟦Horde=Orda⟧.", 0x3e605db7, 0x4dc50313, 0xfe9369ec, nil, 0x37f5f90f, "...m." },
  [4681] = { "Trascinata a riva", "Recupera i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ dalla Skeletal Sea Turtle nelle acque a ovest di Auberdine, poi torna ad Auberdine e parla con Gwennyth Bly'Leggonde.", "Quella creatura spiaggiata non è un caso isolato qui a ⟦Darkshore=Rivafosca⟧. Ce ne sono altre lungo la costa e perfino in acqua. Vorrei che tu ne esaminassi un'altra di cui siamo a conoscenza; è stata segnalata in acqua, proprio a ovest di Auberdine, vicino a una nave affondata. Torna da me con qualunque cosa tu riesca a recuperare che possa aiutare le nostre ricerche.\n\nInoltre, durante i tuoi viaggi potresti trovare altre creature. Se dovessi scoprire qualcosa, ti prego, faccelo sapere!", "Una volta che avrai esaminato i resti della creatura nell'acqua a ovest di qui, dovrei poter presentare un rapporto adeguato al ⟦Temple of the Moon=Tempio della Luna⟧ di Darnassus. Forse allora saremo più vicini a scoprire perché queste povere creature scelgono di finire la loro vita spiaggiate sulla costa di ⟦Darkshore=Rivafosca⟧.", "Oggi ci sei stat<o/a> di enorme aiuto; ora abbiamo buone possibilità di svelare il mistero del perché queste creature si spiaggino sulla costa di ⟦Darkshore=Rivafosca⟧. L'idea che possano fuggire dalla zona intorno a Teldrassil è inquietante. Se dovessi incontrarne altre nei tuoi viaggi, fammelo sapere. Le nostre ricerche qui sono appena agli inizi.\n\nA nome del ⟦Temple of the Moon=Tempio della Luna⟧, accetta questo come ringraziamento per il tuo impegno. Grazie, {name}!", 0x8079e34a, 0x149950e7, 0xcc7a3f7b, 0x32bf10da, 0xa60fc069, "....." },
  [4722] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "Trovi la carcassa di una tartaruga marina che si era arenata sulla costa di ⟦Darkshore=Rivafosca⟧ tempo fa. È stata spolpata dai murloc che si sono accampati attorno ai resti della creatura. Eppure sui resti sembrano esserci ancora dei campioni adatti, che Gwennyth Bly'Leggonde ad Auberdine potrebbe usare.", "Salve, {name}: hai scoperte da riferire su creature arenate sulla riva?", "Un'altra scoperta da studiare: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x3b1c0992, 0xb04a5a8b, 0x3d413149, 0x1ac8bd61, 0x9e7fd774, "....." },
  [4723] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "I resti di un gigantesco plesiosauro, molto più grande di quelli che ci si aspetterebbe di trovare a ⟦Darkshore=Rivafosca⟧, giacciono arenati sulla riva di ⟦Mist's Edge=Costa Bruma⟧. Non si sa come questa creatura sia arrivata qui; il gruppo di murloc che ora banchetta con la sua carcassa sembra troppo debole, anche in gran numero, per aver abbattuto la bestia.\n\nAnche se in parte è stata spolpata, ne resta abbastanza per prelevare un campione da far studiare a Gwennyth Bly'Leggonde ad Auberdine.", "Forse un giorno troveremo il modo di impedire a queste povere creature di morire inutilmente sulla costa di ⟦Darkshore=Rivafosca⟧. Fino ad allora, dobbiamo continuare le nostre ricerche!\n\nSalve, {name}: che notizie mi porti?", "Un'altra scoperta: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x4bb68b2b, 0xc0ba3e69, 0x9a0bf524, 0x919b7748, 0x3513dc87, "....." },
  [4725] = { "Tartaruga marina spiaggiata", "Porta la ⟦Strangely Marked Box=Cassa con Marchio Strano⟧ a Gwennyth Bly'Leggonde, ad Auberdine.", "Altri resti di tartaruga marina giacciono spiaggiati lungo la costa. Questi hanno una portantina abbandonata legata al guscio della tartaruga. Forse questa creatura è stata spinta a riva da esseri sconosciuti invece di arenarsi da sola, come lasciavano pensare alcuni degli altri resti. Ora i murloc Greymist hanno fatto dei resti di questa creatura la loro casa, e si nutrono della carcassa.\n\nNella portantina trovi una cassa con strani segni; forse Gwennyth Bly'Leggonde ad Auberdine saprà interpretarli.", "È un piacere rivederti, {name}. Stiamo facendo grandi progressi nello svelare il mistero del perché maestose creature marine si arenino sulla costa di ⟦Darkshore=Rivafosca⟧, ma a quanto pare ogni risposta solleva altre due domande.\n\nSei qui per offrirci altro aiuto nelle nostre ricerche?", "Ho sentito parlare del tipo di portantine che hai trovato sul dorso della tartaruga. Credo proprio che siano portantine dei naga, usate sia in battaglia sia per trasportare le loro provviste sulla terraferma. I segni sulla cassa che hai trovato sono dei naga; questo spiegherebbe la loro presenza invasiva nell'estremo nord di ⟦Darkshore=Rivafosca⟧.\n\nManderò questa cassa a Darnassus insieme al resto delle tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0xbf35a518, 0xeaee6b01, 0x3dd5d2a8, "....." },
  [4727] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "I resti scheletrici di una tartaruga marina giacciono nella sabbia delle spiagge settentrionali di ⟦Darkshore=Rivafosca⟧. I murloc Greymist non hanno trovato questa carcassa, oppure l'hanno trovata e se ne tengono alla larga per qualche motivo sconosciuto. In ogni caso, della tartaruga resta abbastanza da portarne un campione a Gwennyth Bly'Leggonde, ad Auberdine, perché il ⟦Temple of the Moon=Tempio della Luna⟧ lo studi.", "Ben ritrovat<o/a>, {name}: hai trovato altre creature spiaggiate di cui il ⟦Temple of the Moon=Tempio della Luna⟧ dovrebbe sapere?", "È interessante che i murloc non fossero presenti in questo luogo; ne terremo conto mentre studiamo i resti di questa creatura! Grazie per il tuo impegno, {name}; il ⟦Temple of the Moon=Tempio della Luna⟧ vorrebbe che ti dessi questo, come compenso per il tuo tempo.", 0x3b1c0992, 0xb04a5a8b, 0x571231c8, 0x7d319b8f, 0x07b7db83, "....." },
  [4728] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "La carcassa di quello che sembra un gigantesco mammifero marino giace in parte sventrata sulla spiaggia. Una carriola e vari attrezzi sono abbandonati accanto a questa enorme creatura marina spiaggiata, come se qualcuno avesse già tentato di studiarla. Anche se i murloc l'hanno saccheggiata, ne resta abbastanza da raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.", "Ben ritrovat<o/a>, {name}! Cosa ti riporta ad Auberdine? Sei qui per riferire un'altra scoperta, forse?", "Ah, credo che tu ne abbia scoperta una che inizialmente stava esaminando la Lega degli Esploratori. Hanno una presenza qui a ⟦Darkshore=Rivafosca⟧, e avevano detto che stavano studiando una delle creature spiaggiate finché i murloc non li hanno cacciati. A quanto pare sei riuscit<o/a> dove noi due abbiamo fallito. Ti prego, accetta questo compenso a nome del ⟦Temple of the Moon=Tempio della Luna⟧.", 0x4bb68b2b, 0xc0ba3e69, 0xb92ea900, 0x2d08586e, 0xc17c3fc8, "....." },
  [4730] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "Sulla spiaggia giace la carcassa mezza divorata di quello che forse era un enorme mammifero marino. Una banda di murloc, più forti di quelli che si trovano vicino ad Auberdine, si è stabilita attorno alla creatura morta. Della creatura resta abbastanza da poter consegnare un campione adeguato delle sue ossa a Gwennyth Bly'Leggonde, ad Auberdine.", "Salve di nuovo, {name}! Sei qui per riferire un'altra scoperta?", "Le ossa che hai portato appartengono a mansueti mammiferi marini che, si sa, abitano le acque attorno alla base di Teldrassil. Non si era mai saputo che si spiaggiassero in modo violento, come invece fanno i plesiosauri. Perché queste creature avrebbero fatto una cosa simile, mi chiedo? Beh, forse lo studio dei loro resti darà i frutti di conoscenza che cerchiamo.\n\nAncora grazie per il tuo aiuto. Ti prego, accetta questo compenso da parte del ⟦Temple of the Moon=Tempio della Luna⟧.", 0x4bb68b2b, 0xc0ba3e69, 0xe841063a, 0xd044bb6e, 0x6ea9c612, "....." },
  [4731] = { "Tartaruga marina spiaggiata", "Porta la ⟦Strangely Marked Box=Cassa con Marchio Strano⟧ a Gwennyth Bly'Leggonde, ad Auberdine.", "Un altro insieme di resti di tartaruga marina giace spiaggiato sulla costa. A questi resti è agganciato per metà al guscio un carro abbandonato. Forse questa creatura è stata spinta a riva da esseri sconosciuti invece di arenarsi da sola, come lasciavano pensare alcuni degli altri resti. Dei potenti murloc Greymist hanno fatto della carcassa di questa creatura la loro attuale dimora.\n\nNel carro trovi una cassa con strani segni; forse Gwennyth Bly'Leggonde, ad Auberdine, potrà capirne il significato.", "Ben ritrovat<o/a>, {name}. Il lavoro che hai svolto per il ⟦Temple of the Moon=Tempio della Luna⟧ è stato eccezionale. Saremo benedetti da altri tuoi sforzi in nostro favore?", "Ho sentito parlare del tipo di carro trovato sul dorso di quella tartaruga. Credo proprio che siano carri dei naga, usati sia in battaglia sia per trasportare i loro rifornimenti sulla terraferma. I segni sulla cassa che hai trovato sono dei naga; forse la creatura che hai scoperto è stata uccisa mentre si dirigeva più a sud... forse verso ⟦Ashenvale=Valtetra⟧?\n\nMi assicurerò di mandare questa cassa a Darnassus insieme alle altre tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0x8653ac9e, 0x69e011cf, 0xb192bb2e, "....." },
  [4732] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "Trovi la carcassa di una tartaruga marina che si era arenata sulla costa di ⟦Darkshore=Rivafosca⟧ qualche tempo fa. È stata spolpata quasi del tutto dai murloc Greymist, gli stessi che ora si sono accampati intorno ai resti della creatura. Tuttavia, sui resti sembrano esserci ancora dei campioni adatti, che Gwennyth Bly'Leggonde, ad Auberdine, potrebbe utilizzare.", "Salute di nuovo, {name}: hai altre scoperte da riferire al ⟦Temple of the Moon=Tempio della Luna⟧?", "Hai trovato altre creature spiaggiate, {name}? Un tempo le tartarughe marine si vedevano spesso giocare ai piedi di Nordrassil, prima che venisse distrutto. Con la nascita di Teldrassil, però, queste creature si sono viste in numero sempre minore. Alcune, come abbiamo scoperto, vengono a morire qui per qualche ragione sconosciuta.\n\nForse il tuo aiuto svelerà il mistero che abbiamo davanti. Accetta questo in cambio dei resti che hai fornito per i nostri studi.", 0x3b1c0992, 0xb04a5a8b, 0x149a42d1, 0x068b830b, 0x96ba0af6, "....." },
  [4733] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a Gwennyth Bly'Leggonde ad Auberdine.", "Quelli che sembrano i resti di un gigantesco squalo volpe sono stati portati a riva nell'insenatura rocciosa della ⟦Twilight Shore=Riva del Crepuscolo⟧. Lo squalo è parecchie volte più grande di qualsiasi altro squalo volpe avvistato da queste parti. Da dovunque sia venuta, questa creatura non sembra originaria di ⟦Darkshore=Rivafosca⟧.\n\nAnche se la creatura è stata fatta a pezzi in alcuni punti, ne resta abbastanza per raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.", "Sia ringraziata Elune: sono lieta di rivederti, car<o/a> {name}. Il lavoro del Tempio della Luna sugli strani spiaggiamenti continua qui a ⟦Darkshore=Rivafosca⟧. Hai forse qualcos'altro da offrirci?", "Le dimensioni dello squalo volpe di cui parli sono sbalorditive. Anche i più vecchi squali volpe di questa regione raggiungono solo una frazione di quella grandezza. Sebbene si sapesse di alcuni esemplari più grandi vicino a Teldrassil, il loro numero è calato costantemente. Non posso fare a meno di chiedermi se lo spiaggiamento di queste creature sia in qualche modo collegato.\n\nMentre analizziamo le ossa che ci hai portato, accetta questo da parte del ⟦Temple of the Moon=Tempio della Luna⟧. Grazie, {name}.", 0x4bb68b2b, 0xc0ba3e69, 0x88008738, 0x2ba63290, 0xa5eb453e, "....." },
  [4736] = { "In cerca di Menara Voidrender", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Ah, salve, {name}. Stai facendo buoni progressi nel tuo addestramento. Così buoni, anzi, che credo tu meriti una ricompensa per il tuo impegno, e per non esserti ancora fatt<o/a> corrompere dall'arcano.\n\nSe ti interessa, cerca Menara Voidrender a ⟦Ratchet=Porto Paranco⟧. Al momento alloggia nella torre di Strahad Farsan, che domina la città.\n\nNon è molto cordiale, {name}, quindi non aspettarti lodi. Ma se lavori sodo, farà in modo che tu non resti a mani vuote.", nil, "Ah, ti manda Briarthorn. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x1f30d3ac, nil, 0xa4bfa39e, "...m." },
  [4737] = { "In cerca di Menara Voidrender", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Hmph, continui a cercare di diventare più potente. Io dico che è solo questione di tempo prima che la corruzione e la dipendenza si impadroniscano di te e tu diventi schiav<o/a> di ciò che cerchi di dominare.\n\nPuah! Sei <uno/una> <stolto/stolta>! Il tempo mi darà ragione, nient'altro... solo il tempo.\n\nMa a quanto pare non tutti sono d'accordo con Zevrost. Sembra che Menara voglia creare strumenti per renderti più potente e per imbrigliare la tua forza. Se ti interessa, va' a ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Sta lassù, da dove domina la città.", nil, "Ah, ti manda Zevrost. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x1ffc2c9b, nil, 0x76faa6d0, "...m." },
  [4738] = { "In cerca di Menara Voidrender", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Mettiamo in chiaro una cosa, {name}: non credo che tu sia pront<o/a> per simili responsabilità. Non penso che un novizio debba mai partecipare alla creazione di un oggetto di potere, men che meno uno così poco messo alla prova.\n\nMa non spetta a me deciderlo. Lo decidono i poteri superiori, o almeno quelli che desiderano concederti simili doni.\n\nSe vuoi saperne di più, ti consiglio di cercare Menara Voidrender a ⟦Ratchet=Porto Paranco⟧. Di solito risiede nella torre che sovrasta la città portuale.", nil, "Ah, ti manda Demisette. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0x7c0126bb, 0x28c69a48, nil, 0xb18020cd, "...m." },
  [4739] = { "In cerca di Menara Voidrender", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "{class}! Sì, proprio tu!\n\nNon hai tutto l'equipaggiamento, ma si vede chiaramente che sei pront<o/a>: l'aria intorno a te trasuda una sicurezza maggiore. Sì, ora lo vedo.\n\nMenara Voidrender ti insegnerebbe qualcosa, se ti senti pront<o/a>. Passa il suo tempo a istruire nell'arcano gli studenti più giovani. Fa persino dei doni a chi supera le sue prove.\n\nSe ti interessa, va' a ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Sta sopra la città, nella torre di Strahad.", nil, "Ah, ti manda Kaal. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x047f9579, nil, 0x6556e634, "...m." },
  [4740] = { "RICERCATO: Murkdeep!", "Trova e uccidi il murloc noto come Murkdeep. Si ritiene che la creatura difenda le capanne dei murloc lungo la riva, a sud di Auberdine.\n\nRiferisci la morte di Murkdeep alla sentinella Glynda Nal'Shea, ad Auberdine.", "Attenzione!\n\nSi offre una ricompensa per la morte del murloc «Murkdeep». Questa ripugnante bestia è responsabile della morte di almeno una Sentinella ed è sospettata di aver fatto affondare almeno due navi da carico nelle acque al largo di ⟦Darkshore=Rivafosca⟧!\n\nMurkdeep è stato avvistato l'ultima volta in un accampamento di capanne dei murloc a sud di Auberdine, e si ritiene che protegga le capanne. La ricompensa per questa taglia va richiesta alla sentinella Glynda Nal'Shea, ad Auberdine.\n\nIl Consiglio del villaggio di Auberdine", "Salute, {class}: in che cosa possono aiutarti oggi le ⟦Sentinels=Sentinelle⟧? Forse sei qui per informarti sulla taglia su Murkdeep?", "Be', a quanto pare non sei qui solo per informarti! I cittadini saranno felici di sapere che stanotte dormiranno un po' più tranquilli e al sicuro.\n\nOggi sei <stato/stata> il braccio della giustizia per la gente di Auberdine, {name}. Per questo vorrei offrirti questa degna ricompensa... per <un/una> ver<o/a> <eroe/eroina> della gente di Auberdine.", 0xcf1b7374, 0xd0180f37, 0x68da692c, 0x1e209309, 0xb1230932, "....." },
  [4761] = { nil, "Parla con Thundris Windweaver ad Auberdine.", "Le informazioni raccolte esplorando l'accampamento dei mezzorsi dovrebbero arrivare a Thundris Windweaver. Con grande generosità fa da anziano di Auberdine, e guida con saggezza e giustizia la vita quotidiana del villaggio. Ti prego, condividi con lui ciò che hai scoperto finora sulla situazione dei mezzorsi.\n\nCredo che abbia delle idee sue sulle ragioni della loro corruzione. Forse potrai lavorare con lui a un piano per ristabilire l'equilibrio della natura qui!", nil, "Ben trovat<o/a>, {class}. La tua esplorazione della situazione dei mezzorsi arriva in un momento propizio per noi di Auberdine. Da tempo non abbiamo a che fare solo con abitanti della foresta ormai apertamente ostili alla nostra presenza, ma anche con la corruzione vera e propria della foresta stessa. Spero che tu possa dare aiuto ad Auberdine in questi tempi difficili.", 0xa1402122, 0xe04eac93, 0x5978da41, nil, 0x8e442694, "e..m." },
  [4762] = { "Il ⟦Cliffspring River=Fiume Altafonte⟧", "Viaggia a nord di Auberdine fino alla prima cascata lungo il ⟦Cliffspring River=Fiume Altafonte⟧ e preleva un campione dalla pozza che si trova lì.\n\nTorna da Thundris Windweaver ad Auberdine con il ⟦Cliffspring River Sample=Campione del Fiume Altafonte⟧.", "Il ⟦Cliffspring River=Fiume Altafonte⟧ ha cominciato a diventare torbido e corrotto. Si getta nella ⟦Mist's Edge=Costa Bruma⟧, e temo che presto le sue acque raggiungeranno Auberdine. Sospetto che la causa della contaminazione siano i mezzorsi Blackwood risalendo il fiume, ma sospetto anche che non ne siano la vera origine.\n\nPrendi questa provetta e va' alla foce del fiume, a nord di qui. Prosegui verso l'interno fino alla prima cascata e preleva un campione dalla pozza che si trova lì. Vedrai un ponte sopra di te. Quando avrai il campione, torna da me ad Auberdine.", "L'inquinamento del ⟦Cliffspring River=Fiume Altafonte⟧ è solo l'inizio di una tendenza allarmante qui a ⟦Darkshore=Rivafosca⟧. Il campione che porterai ci aiuterà a definire un piano... un piano d'attacco, comincio a sospettare.", "Non sorprende quanto sia contaminata quest'acqua, ma guarda quanto sta diventando putrida! Sembra che bisogni agire prima piuttosto che poi, eh, {name}?\n\nA est di qui c'è ⟦Felwood=Vilbosco⟧: è la vera fonte di questa corruzione, che ho già visto in passato. Prevedo che questo campione lo confermerà. Potremmo riuscire a trovare una cura qui, ma per provarci avremo bisogno di aiuto. Quando verrà quel momento, {name}, spero che potrai darci l'aiuto di cui abbiamo bisogno.", 0x732408df, 0x9c875372, 0x31c4d12c, 0xcd07cafd, 0x405bb8d6, "....." },
  [4763] = { "I Blackwood corrotti", "Riempi la ⟦Empty Cleansing Bowl=Ciotola per la Pulizia Vuota⟧ al pozzo lunare di Auberdine.\n\nRaccogli un campione di frutta, di noci e di cereali dagli accampamenti settentrionali dei mezzorsi Selvanera.\n\nMescola il contenuto della ciotola e posala vicino al falò più vicino al ⟦Cliffspring River=Fiume Altafonte⟧, nell'accampamento settentrionale, per evocare il corruttore satiro.\n\nPrendi il ⟦Talisman of Corruption=Talismano della Corruzione⟧ e portalo a Thundris Windweaver, ad Auberdine.", "Abbiamo scoperto che una delle fonti della corruzione dei mezzorsi sono i satiri. Esercitano il loro dominio tramite talismani attraverso cui incanalano la magia. Se i mezzorsi hanno una possibilità di salvezza, dobbiamo attirare allo scoperto il corruttore satiro e prendergli quel talismano!\n\nRiempi questa ciotola al nostro pozzo lunare e prendi dei campioni del cibo dei mezzorsi dal loro accampamento settentrionale. Mescolali e metti la ciotola vicino al falò accanto al fiume: i mezzorsi che ne mangeranno saranno purificati quanto basta per attirare allo scoperto il corruttore satiro... che poi dovrai uccidere!", "Il ⟦Talisman of Corruption=Talismano della Corruzione⟧ è un congegno sinistro che serve solo a pervertire l'equilibrio della natura. Quando avrai sottratto questo oggetto al satiro che tormenta i mezzorsi e me lo porterai perché lo distrugga, oggi avremo ottenuto una grande vittoria!", "Abbiamo appena iniziato questa guerra per strappare la nostra foresta alle forze della corruzione, ma oggi abbiamo vinto una battaglia! {name}, la gente di Auberdine ha con te un debito di gratitudine che non sarà mai facile ripagare. Accetta questo insieme ai nostri ringraziamenti. Ciò che abbiamo imparato qui oggi potrebbe un giorno liberare per sempre i nostri amici mezzorsi dalle catene del tormento.", 0x2f8f88d9, 0xbffe0b22, 0xb9e3e349, 0x893d1d9e, 0xa947b3e7, "....." },
  [4767] = { "Cavaliere di viverne", "Porta 10 Uova di Viverna di ⟦Highperch=Covoalto⟧ a Elu al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Mi è stato affidato il compito di reclutare altre viverne per i cavalieri di viverne più esperti. Il loro numero cresce e io stesso spero un giorno di diventare un cavaliere di viverne. Però non riusciamo ad addestrare abbastanza viverne per stare al passo con la richiesta. Forse puoi aiutarmi, {name}.\n\nHo bisogno che tu vada a ⟦Highperch=Covoalto⟧ a raccogliere alcune uova di viverna. Da qui, dirigiti a nord-ovest lungo le pareti del canyon fino a una rampa che ti porterà a ⟦Highperch=Covoalto⟧. Fai attenzione: le viverne proteggono gelosamente le loro uova e non saranno gentili con gli intrusi.", "{name}, hai recuperato le uova di viverna che cerco? Non vedo l'ora di iniziare il mio addestramento da cavaliere di viverne!", "Perfetto! Con queste uova spero di fare il prossimo passo per diventare un cavaliere di viverne. Ecco un segno della mia gratitudine; che la buona caccia ti sorrida sempre, {class}.", 0xb115ace3, 0x1b0bf486, 0x8c494c01, 0x55a37b15, 0x2fee56fe, "....." },
  [4770] = { "Ritorno a casa", "Scorta Pao'ka Swiftmountain fuori da ⟦Highperch=Covoalto⟧, poi parla con Motega Firemane all'⟦Whitereach Post=Accampamento di Manto Bianco⟧.", "Aiutami, ti prego, {class}! Mi nascondo qui a ⟦Highperch=Covoalto⟧ da un po' ormai, e sono giorni che non vedo un volto amico. Sono venuto qui a studiare le viverne e credo di essermi avvicinato un po' troppo. Dopo che mi hanno cacciato da uno dei nidi, mi sono perso.\n\nDevo tornare all'⟦Whitereach Post=Accampamento di Manto Bianco⟧! Motega non sa che sono sparito e si infurierà quando scoprirà che mi sono avventurato a ⟦Highperch=Covoalto⟧ da solo.\n\nL'⟦Whitereach Post=Accampamento di Manto Bianco⟧ è appena a est di qui... ti prego, portami là!", nil, "Cosa!? Se avessi saputo che Pao'ka Swiftmountain sarebbe andato a ficcare il naso a ⟦Highperch=Covoalto⟧, l'avrei incatenato a un totem! Suo padre era restio a lasciarlo venire con me a ⟦Thousand Needles=Millepicchi⟧. Siamo venuti qui per studiare le diverse creature che abitano queste splendide terre.\n\nApprezzo l'aiuto che hai dato a Pao'ka. Spero che questo ripaghi qualsiasi disavventura ti sia costata questa impresa.", 0x495ac7e2, 0xf36b8eeb, 0x9c7efe0f, nil, 0xc6301876, "...m." },
  [4781] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta un ⟦Gold Bar=Lingotto d'Oro⟧ a Xizk Goodstitch nella Valle di Rovotorto.", "Il tuo prossimo compito è semplice come il primo, ma dovrai cercare aiuto.\n\nMi serve del filo d'oro per ricamare il mantello, ma il filo d'oro non è facile da trovare, e pochissimi sanno farlo. Per fortuna, uno che è fedele alla nostra causa ne conosce i segreti ed è disposto ad aiutare chi sale nei nostri ranghi.\n\nPorta un lingotto d'oro a Xizk Goodstitch alla ⟦Booty Bay=Baia del Bottino⟧. È un maestro sarto e sarà felice di filarlo per te. I lingotti d'oro li fondono i minatori esperti. Chiedi aiuto a un minatore.", "Lingotti d'oro, sì... sì. Portamene uno e vedremo cosa si può fare per filarti un po' di filo. Nel frattempo, ti suggerirei di concentrare i tuoi sforzi sul diventare più potente. Le prove più dure ti aspettano ancora. E fidati... vorrai essere più preparat<o/a>, per quanto potente tu creda di essere.", "Perfetto, {name}. Sono contento che tu abbia trovato così in fretta un minatore che ti aiutasse. O hai fatto il lavoro da te? In ogni caso, hai fatto bene. Questo sarà perfetto per il filo.\n\nCi vorrà un po' di tempo per produrlo, quindi dovrai tornare: in realtà lo mando a una principessa che teniamo rinchiusa in una torre e il cui unico compito è filare filo d'oro... no, sul serio. Dico davvero... va bene, non proprio.", 0x7fee9266, 0x16a84461, 0x54d5ef6e, 0x024ea4f3, 0x476cbcd4, "....." },
  [4782] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Torna da Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Torna da Menara e dille che ci vorrà un po' di tempo, ma non deluderò né lei... né te. Dille di farti finire di raccogliere il resto dei componenti: per allora il filo dovrebbe essere pronto. Potrai tornare a prenderlo.\n\nBuona fortuna, {name}. Ah, e già che ci sei salutami Strahad. Quel vecchio matto... piazzare una torre proprio lì accanto a ⟦Ratchet=Porto Paranco⟧... roba da pazzi.", nil, "Bene, sei tornat<o/a>, {name}. E dov'è il filo?\n\nAh, capisco. È accettabile. Il goblin e suo fratello non ci hanno mai delusi finora: immagino sia comprensibile che non l'avesse pronto subito. E sia... nel frattempo abbiamo altre cose di cui occuparci.\n\nSei pront<o/a> per il passo successivo?", 0x7fee9266, 0xb874296f, 0xe71c1200, nil, 0xce0868a5, "...m." },
  [4783] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta 10 Fiala di Sangue di Furiatorva e 1 ⟦Lesser Infernal Stone=Pietra Infernale Inferiore⟧ a Menara Voidrender nelle ⟦Barrens=Savane⟧.", "I prossimi componenti si trovano a ⟦Desolace=Desolanda⟧, molto a ovest delle ⟦Barrens=Savane⟧ e persino delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.\n\nLaggiù il caos regna ancora dopo la Separazione. Saranno messe alla prova sia la tua forza che la tua astuzia: affronterai creature dell'odio e anche della Legione Infuocata.\n\nDai satiri Furiatorva a nord-est, portami il loro sangue. Dagli infernali minori della ⟦Mannoroc Coven=Congrega di Mannoroc⟧, portami una pietra infernale inferiore.\n\nUseremo entrambi per confezionare la tua tonaca.", "⟦Desolace=Desolanda⟧ non è una terra gentile: naga, giganti, satiri, la Legione Infuocata... tutti loro, e i clan di centauri in guerra tra loro, rendono la regione pericolosa se non stai attent<o/a>.\n\nCome ti ho detto, metterà alla prova non solo la tua forza e la tua astuzia, ma anche la tua pazienza. Sta' in guardia in quelle terre, {name}.", "Eccellente, {name}. Questi andranno benissimo. Li preparerò ora, mentre tu passi agli ultimi due componenti. Sei pront<o/a>?", 0x7fee9266, 0xfd7ed7f0, 0x055bed5e, 0x9a052ff2, 0xfb7327df, "....." },
  [4784] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta del ⟦Fine Gold Thread=Filo Dorato Pregiato⟧, 2 Carbone Infuocato e un Soul Shard a Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Ora mi servono solo tre cose, {name}, poi potremo finire la tua tonaca.\n\nPrima di tutto, il filo dorato pregiato che Xizk sta preparando per te. Torna da lui alla ⟦Booty Bay=Baia del Bottino⟧ e fattelo dare.\n\nSecondo, portami due carboni infuocati dagli elementali del fuoco degli ⟦Arathi Highlands=Altopiani d'Arathi⟧. Se ricordo bene, si trovano a ovest, vicino al ⟦Thoradin's Wall=Muro di Thoradin⟧.\n\nInfine, un frammento d'anima creato da te.\n\nQuando avrai tutti i componenti, torna qui alla torre e completerò la tonaca per te.", "Presto, {name}. Te lo prometto. La tonaca sarà più che adeguata alle tue esigenze e di certo ti darà un vantaggio sui tuoi avversari.", "Eccellente, {name}! I componenti sono riuniti e siamo pronti.\n\nSono certo che ne sarai soddisfatt<o/a>.", 0x7fee9266, 0x57678e6a, 0x01e0638a, 0x10b8afc4, 0x33387de3, "....." },
  [4786] = { "La veste ultimata", "Aspetta che Menara Voidrender finisca la tua veste, poi parla di nuovo con lei.", "Ora metterò insieme la veste per te. Ci vorrà solo qualche istante. Non allontanarti.", "Un momento, {name}...", "È fatto, {name}. Eccola. Indossala con orgoglio.\n\nHai lavorato sodo, e vedo grandi cose nel tuo futuro. Ricorda: resistere alla corruzione che accompagna il nostro cammino richiede grande volontà e forza d'animo. Finché la tua volontà resterà tua, avrai grande successo.", 0x6458d4ea, 0x1f58f886, 0xac1a561e, 0x5118b45f, 0x7b3d8bf4, "....." },
  [4787] = { "L'⟦Ancient Egg=Uovo Antico⟧", "Porta l'⟦Ancient Egg=Uovo Antico⟧ a Yeh'kinya, a Tanaris.", "La Profezia di Mosh'aru parla di un uovo antico. È una reliquia dei tempi in cui i troll governavano vasti imperi, e ha il potere di contenere l'essenza di Hakkar. Potrebbe essere l'unico modo per proteggere il nostro mondo dalla sua malvagità.\n\nPortami l'uovo antico, {name}. Si dice che sia nascosto nelle profondità di ⟦Jintha'Alor=Jintha'alor⟧, nelle Entroterre, in una grotta dietro l'anfiteatro in cima alla città.", "Hai l'uovo antico? Sento grandi forze che si risvegliano, e temo che il tempo stringa.", "Ah, hai l'uovo! M'inchino a te, {name}. La tua forza e il tuo coraggio saranno ricordati a lungo.", 0x145cd452, 0x848c5ffa, 0x907bfabd, 0xec9c0814, 0x7bde200a, "....." },
  [4811] = { "Il cristallo rosso", "Viaggia a est di Auberdine e cerca un grosso cristallo rosso lungo la catena montuosa orientale di Rivafosca. Riferisci ciò che trovi alla sentinella Glynda Nal'Shea, ad Auberdine.", "A est di qui si aggirano lunagufi ostili, sempre più numerosi. Un tempo li si riteneva creature gentili, quasi mistiche. Anche se alcuni continuano a venerarli, la sicurezza di Auberdine mi obbliga a una visione più realistica.\n\nHo ricevuto rapporti secondo cui i lunagufi sono attirati da un grosso cristallo rosso lungo la catena montuosa orientale di Rivafosca. Nessuno ha idea di cosa sia quel cristallo, e nemmeno se esista davvero. Voglio che tu vada a trovarlo e che mi riferisca ciò che scopri.", "Cos'hai da riferire su quel cristallo rosso? Esiste davvero?", "Dunque il cristallo esiste, {name}? Affascinante... comunque, hai svolto bene il tuo compito; ottimo lavoro!\n\nChe cos'è esattamente questo cristallo? È solo una domanda in un mare di domande. Un'altra che mi viene in mente è perché i lunagufi siano attirati da questo oggetto. Il cristallo è di natura benigna o ha uno scopo più sinistro?\n\nHo molte altre domande, ma dovremo esaminare da vicino quel cristallo per avere qualche risposta.", 0x5ae7f813, 0x8d4ec0d3, 0x69995f12, 0x84875e53, 0xe63afa83, "....." },
  [4812] = { "Mentre l'acqua scorre", "Riempi la ⟦Empty Water Tube=Fialetta d'Acqua Vuota⟧ al pozzo lunare di Auberdine, poi esamina il cristallo rosso lungo la parete montuosa orientale di Rivafosca.", "Prendi questa fiala vuota e riempila con un po' d'acqua del pozzo lunare, qui ad Auberdine. Una magia così potente dovrebbe darci un indizio sulla composizione del cristallo. Per farlo, verserai il liquido sul cristallo; al resto penserà l'acqua.\n\nAnche se non prevedo che ti accada nulla di male, voglio comunque che tu stia attent<o/a>. Sopra di noi, a est, c'è ⟦Felwood=Vilbosco⟧; se quel cristallo è legato a quel luogo, come sospetto, potrebbe rivelarsi molto pericoloso.", "Il cristallo sembra del tutto estraneo al paesaggio boscoso di ⟦Darkshore=Rivafosca⟧. Ti sembra di sentire un lievissimo ronzio provenire dalle sue profondità.", "Sei arrivat<o/a> di nuovo al misterioso cristallo. Togli il tappo alla fialetta d'acqua del pozzo lunare e ne versi con cautela il contenuto sulla sommità del cristallo. Mentre l'acqua scorre lungo le sue strutture reticolari, vedi la superficie opaca diventare trasparente...", 0xdefb4541, 0xe834c2df, 0x29e90dd5, 0xb62a1acf, 0x9b8b44cb, "....." },
  [4813] = { "I frammenti all'interno", "Riferisci ciò che hai scoperto alla sentinella Glynda Nal'Shea, ad Auberdine.", "L'acqua del pozzo lunare ha rivelato che all'interno del cristallo sono incastonati alcuni piccoli frammenti d'osso, oltre a metà di una mandibola. La mandibola sembra appartenere a un umanoide, ma non se ne può essere certi senza spaccare il cristallo, un'impresa che perfino la magia più potente troverebbe quasi impossibile.\n\nPortato a termine il compito, non resta che tornare a riferire alla sentinella Glynda Nal'Shea, ad Auberdine.", nil, "Be', a quanto pare, anche se ora sappiamo di più su questo cristallo, il risultato sono altre domande senza risposta!\n\nPorterò le informazioni che hai scoperto al consiglio qui ad Auberdine. Forse sapranno quale linea d'azione seguire riguardo a questo cristallo. Sempre che ce ne sia una da intraprendere; per ora la minaccia resta abbastanza lontana, a est, da non nuocerci.\n\nQuanto a te, prendi questo. Consideralo una ricompensa per un lavoro ben fatto, {name}.", 0xb84b9e71, 0x336ce815, 0x1453b5e8, nil, 0xd3015ad0, "...m." },
  [4821] = { "⟦Alien Egg=Uovo Alieno⟧", "Riporta l'⟦Alien Egg=Uovo Alieno⟧ a Hagar Lightninghoof, al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Circola una voce su un uovo alieno qui a ⟦Thousand Needles=Millepicchi⟧. Chi dice di averlo visto non è riuscito nemmeno ad avvicinarsi abbastanza da esaminarlo per bene. I serpenti sorvegliano l'uovo come se fosse uno dei loro.\n\nVoglio che tu trovi questo uovo alieno e me lo porti, così che possa esaminarlo. Si dice che l'uovo si trovi in una tana di serpenti, ma ce ne sono diverse lungo la base delle pareti rocciose a sud e a nord-est del ⟦Freewind Post=Presidio di Ventolibero⟧.", "Devo sapere di più su questo uovo misterioso: chissà cosa ne uscirà.", "Sì, finalmente... l'uovo misterioso mi è stato finalmente consegnato. Ora, diamo un'occhiata più da vicino... Cosa..! Cos'è questo..?", 0x3030ce44, 0x472a0b24, 0x6e429e9a, 0x5cb94efa, 0xfb1826a4, "....." },
  [4841] = { "Pacificare i centauri", "Uccidi 12 Galak Scout, 10 Galak Wrangler e 6 Galak Windchaser, poi torna dal guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧.", "{name}, ti supplico di dare la caccia a questi centauri. Sentiranno l'ira della nostra vendetta. Attacca l'accampamento dei centauri a nord del ⟦Freewind Post=Presidio di Ventolibero⟧! Che l'ira guidi la tua mano!", "Su, {name}, so che non hai ancora ucciso la tua parte. Dà loro la caccia, e ti darò una ricompensa in segno di gratitudine.", "In segno di gratitudine, questo è per te, {name}.", 0x1d435eac, 0xb4351619, 0x27f17b09, 0x9319ff75, 0x8bb40c71, "....." },
  [4865] = { "Serpente selvaggio", "Riferisci le tue scoperte a Motega Firemane.", "Se non l'avessi visto con i miei occhi non ci avrei mai creduto. La Vendetta è giunta a ⟦Thousand Needles=Millepicchi⟧!\n\n<Hagar si asciuga la fronte.>\n\n{name}, devi agire in fretta! Va' subito a cercare Motega Firemane; si trova all'⟦Whitereach Post=Accampamento di Manto Bianco⟧, appena a nord-ovest del ⟦Freewind Post=Presidio di Ventolibero⟧ lungo la strada. Lui saprà cosa fare!", nil, "La Vendetta! Dunque la leggenda di Arikara è vera. Questo è davvero un problema da risolvere immediatamente.", 0x612f028d, 0xc8e5a036, 0x7e5035fc, nil, 0x1fdaed2a, "...m." },
  [4881] = { "Complotto omicida", "Avverti Kanati Greycloud, all'⟦Whitereach Post=Accampamento di Manto Bianco⟧, del complotto per ucciderlo.", "Il tauren Kanati Greycloud ha avuto l'ardire di piantare un accampamento di caccia a ⟦Thousand Needles=Millepicchi⟧. Dobbiamo ucciderlo per liberarci di questo accampamento e di tutti quelli che potrebbero seguirlo. Ci raduneremo al piccolo avamposto a sud-ovest del Grande Ascensore.", nil, "Vengono a uccidermi? Mostrerò loro come combatte un tauren!", 0xc85dbd6e, 0x9ca08705, 0x1c5ff84a, nil, 0x4f9dc751, "...m." },
  [4902] = { nil, "Parla con l'Arcidruido Fandral Staghelm, a Darnassus.", nil, nil, nil, nil, 0xf466e7fe, nil, nil, nil, "m.mmm" },
  [4904] = { "Libera, finalmente", "Scorta Lakota Windsong fuori dal ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧, poi parla con Thalia Amberhide al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Arnak crede che ci sposeremo... ma dopo che ho rifiutato la sua proposta è tornato quella notte e mi ha rapita. Mio fratello ha cercato di fermarlo, ma Arnak era troppo forte. Lui... ha ucciso mio fratello e poi mi ha portata qui. Il mio povero fratello...\n\n{name}, puoi scortarmi fuori dal ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧? Ti prego... devo tornare da Thalia! Sarà preoccupatissima per me.", nil, "Grazie, {name}. Nel profondo delle ossa sapevo che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato del tuo coraggio e di come l'hai aiutata a fuggire. Queste cose appartenevano a suo fratello. So che vorrebbe che le avessi tu.", 0x1ba438b0, 0xcbafa782, 0xeb06eed1, nil, 0xf5fd9df3, "...m." },
  [4921] = { "Dispersa in battaglia", "Trova la moglie di Mankrik, poi torna da lui al ⟦Crossroads=Crocevia⟧.", "Stavamo combattendo in un piccolo accampamento tauren quando ci hanno separati: lei da sola teneva a bada tre Mantotergo. Ma erano troppi per noi. Ne ho attirati via alcuni, solo per vederla sopraffatta dai nuovi arrivati. Accecato dalla rabbia mi sono voltato ad affrontare i nemici, ma col loro gran numero mi hanno abbattuto con facilità.\n\nMi sono risvegliato mentre un druido tauren curava le mie ferite: mi aveva trovato sulla ⟦Gold Road=Strada dell'Oro⟧, dove ero caduto.\n\nTi prego, {class}, trova qualche traccia di mia moglie.", "Hai trovato qualche traccia di lei? Il dolore nel petto mi dice che è successo il peggio, ma spero che tu la trovi sana e salva.", "Capisco. Grazie, {class}.", 0xac9b0a79, 0xf3b9fa6f, 0x129c3977, 0xa6107eba, 0xc0eb0cb6, "....." },
  [4961] = { "La purificazione del Globo di Orahil", "Uccidi il Demon of the Orb, poi parla con Tabetha.", "Ah, un globo da evocatore: è da qui che deve venire la corruzione. Dobbiamo esorcizzare il demone che vi è racchiuso, se vuoi usarlo. Questo posso farlo facilmente.\n\nIl compito difficile spetta a te. Dovrai uccidere il demone quando lo libererò.\n\nE dovrai essere rapid<o/a>. Se ci metti troppo, tornerà nel globo e dovremo ricominciare da capo!\n\nQuindi preparati, {name}. Tieni pronti gli incantesimi più potenti e le pozioni a portata di mano, e porta un amico, se ne hai uno. Perché non sarà uno spettacolo piacevole.", "Dovrai uccidere quel demone per cancellare per sempre la sua presenza dal globo, {name}.", "Ben fatto, {name}! Hai dato a quel demone una lezione che non dimenticherà presto. Hai dimostrato grande potere e abilità. Ora credo sia il momento di tornare da Menara con la tua sfera purificata, così potrai farne buon uso.\n\nBuona fortuna, {class}. Forse le nostre strade si incroceranno di nuovo.", 0xa2af51d8, 0x0c09dbd7, 0xef1d65ce, 0x2aeacd11, 0x36989af8, "....." },
  [4962] = { "Frammento di un vilsegugio", "Prendi il ⟦Felhas Ruby=Vil Rubino⟧ e usalo su uno dei Felhound in ⟦Desolace=Desolanda⟧. Una volta riuscit<o/a>, riporta il ⟦Felhas Ruby=Vil Rubino⟧ e lo ⟦Imprisoned Felhound Spirit=Spirito di Vilsegugio Imprigionato⟧ a Menara Voidrender, nelle ⟦Barrens=Savane⟧.", "Dunque hai scelto di catturare l'anima di un vilsegugio. Bene.\n\nPrendi questo rubino: con esso potrai catturare l'anima della creatura. Funziona in modo molto simile a incantesimi che già conosci: quando la creatura è prossima alla morte, usa la gemma e farà il resto del lavoro per te.\n\nTi suggerisco di andare in ⟦Desolace=Desolanda⟧ e di metterti alla prova con uno dei vilsegugi che si trovano lì. Dovrebbero andare benissimo.\n\nQuando ci sarai riuscit<o/a>, porta sia lo spirito catturato sia il rubino a Menara.", "Sì, {name}? Hai scelto? Infernale o vilsegugio?\n\nOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Non è raro che uno stregone preferisca potenziare ancora le proprie doti invece di compensare quelle che gli mancano. A volte sopraffare un nemico è una tattica efficace quanto diventare un incantatore più equilibrato.", "Ah, lo spirito di un vilsegugio. Ben fatto, {name}.\n\nQuando avrò sia lo spirito sia la sfera purificata, li fonderò per te, ma non prima.", 0xcac8654f, 0xdbee1707, 0x3d24b7b3, 0x90161bdb, 0x9222e0a7, "....." },
  [4963] = { "Frammento di un infernale", "Prendi lo ⟦Infus Emerald=Smeraldo Infuso⟧ e usalo su uno degli Infernal in ⟦Desolace=Desolanda⟧. Una volta riuscit<o/a>, riporta lo ⟦Infus Emerald=Smeraldo Infuso⟧ e lo ⟦Imprisoned Infernal Spirit=Spirito di Infernale Imprigionato⟧ a Menara Voidrender, nelle ⟦Barrens=Savane⟧.", "Dunque hai scelto di catturare l'anima di un infernale. Bene.\n\nPrendi questo smeraldo: con esso potrai catturare l'anima della creatura. Funziona in modo molto simile a incantesimi che già conosci: quando la creatura è prossima alla morte, usa la gemma e farà il resto del lavoro per te.\n\nTi suggerisco di andare in ⟦Desolace=Desolanda⟧ e di metterti alla prova con uno degli infernali che si trovano lì. Dovrebbero andare benissimo.\n\nQuando ci sarai riuscit<o/a>, porta sia lo spirito catturato sia lo smeraldo a Menara.", "Sì, {name}? Hai scelto? Infernale o vilsegugio?\n\nOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Non è raro che uno stregone preferisca potenziare ancora le proprie doti invece di compensare quelle che gli mancano. A volte sopraffare un nemico è una tattica efficace quanto diventare un incantatore più equilibrato.", "Ah, lo spirito di un infernale. Ben fatto, {name}.\n\nQuando avrò sia lo spirito sia la sfera purificata, li fonderò per te, ma non prima.", 0x99d101f6, 0xc9a4d7b1, 0x14f7176a, 0x90161bdb, 0x614e3e45, "....." },
  [4964] = { "Il ⟦Orb of Dar'Orahil=Globo di Dar'Orahil⟧ completato", "Aspetta che Menara Voidrender completi il ⟦Orb of Dar'Orahil=Globo di Dar'Orahil⟧, poi parlale di nuovo.", "Mi metterò subito al lavoro per forgiare il tuo globo e infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante assecondare l'arma scelta da uno stregone... e non vedo motivo di abbandonare questa abitudine.", nil, "È fatto, {name}. Dimmi soltanto cosa preferisci: un bastone che richiede l'uso di entrambe le mani, o un globo che ti permetta di usare un pugnale o una spada come arma.\n\nAffrontare un vilsegugio è stata una grande impresa da parte tua. Di certo il tuo oggetto ti servirà bene in futuro. Continua a impegnarti nelle arti, {name}. Attenderò notizie delle tue gesta.", 0x0db266f4, 0xe3749851, 0x7c553bb6, nil, 0x34bb4f9e, "...m." },
  [4965] = { "La conoscenza del Globo di Orahil", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Bene, bene, bene... che piacere vedere che il tuo potere cresce, {name}. Scommetto che saresti quasi pront<o/a> per parlare con Menara Voidrender, nelle ⟦Barrens=Savane⟧. Se non ci hai mai parlato, lascia che te lo dica: non credo di aver mai conosciuto un'altra esperta nella creazione di oggetti (globi, in particolare) capaci di imprigionare persino un demone e piegarlo al nostro volere con tanta facilità.\n\nSe ti interessa, si trova nella torre di Strahad, sopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0xded3c63b, nil, 0xc0e51e95, "...m." },
  [4966] = { "In difesa di Kanati Greycloud", "Proteggi Kanati Greycloud dall'attacco dei centauri.", "Ma i centauri potrebbero essere più di quanto pensassi; ti chiedo, {name}, di combattere al mio fianco contro questi vili assassini.", nil, "Grazie per l'aiuto, {name}. Senza di te non ce l'avrei fatta a respingerli.", 0x87ee9084, 0xb8578399, 0x907deac5, nil, 0xfb6cc9e7, "...m." },
  [4967] = { "La conoscenza del Globo di Orahil", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Ancora <uno/una> sciocc<o/a>, e ancora in cerca dei fronzoli dei mortali. Sì, ti parlo con arroganza. Ti vedo davanti a me e rido. Sei patetic<o/a>!\n\nMa non importa cosa penso io. Importa solo cosa pensano quelli disposti a trattare con te! E in questo caso, contro il mio parere, quelli che hanno un po' di potere ritengono che tu meriti di più.\n\nSe è questo che cerchi, dovresti parlare con Menara Voidrender nella torre sopra ⟦Ratchet=Porto Paranco⟧. Credo che tu l'abbia già incontrata tempo fa.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0xabcb7e15, nil, 0xc0e51e95, "...m." },
  [4968] = { "La conoscenza del Globo di Orahil", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Mmh, sei arrivat<o/a> fin qui... davvero sorprendente. Avrei pensato che la corruzione dell'incanalare l'arcano ti fosse già penetrata fin nell'anima, facendoti impazzire. Che ne dici di spingerti ancora più in là?\n\nSe vuoi mettere alla prova la tua abilità, cerca Menara Voidrender sopra ⟦Ratchet=Porto Paranco⟧, nella torre di Strahad. Ti guiderà lei.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0x4b72c193, nil, 0xc0e51e95, "...m." },
  [4969] = { "La conoscenza del Globo di Orahil", "Parla con Menara Voidrender nelle ⟦Barrens=Savane⟧.", "Ah ah! Te la stai cavando proprio bene, giovane {class}.\n\nCol tempo, infernali e Signori del Terrore si inchineranno davanti a te!\n\nMa finché quel momento non arriverà, dovrai ancora affidarti ad armi forgiate dalle mani delle razze mortali.\n\nSembri pront<o/a> per un'altra di queste creazioni, e se lo desideri, Menara Voidrender vorrebbe parlarti! Si trova vicino alla torre di Strahad che domina la città portuale di ⟦Ratchet=Porto Paranco⟧. Va' da lei quando sei pront<o/a>.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. Posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0x4438376e, nil, 0x5ab9669e, "...m." },
  [4975] = { "Il ⟦Orb of Noh'Orahil=Globo di Noh'Orahil⟧ completato", "Aspetta che Menara Voidrender completi il ⟦Orb of Noh'Orahil=Globo di Noh'Orahil⟧, poi parlale di nuovo.", "Mi metterò subito al lavoro per forgiare il tuo globo e infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante assecondare l'arma scelta da uno stregone... e non vedo motivo di abbandonare questa abitudine.", nil, "È fatto, {name}. Dimmi soltanto cosa preferisci: un bastone che richiede l'uso di entrambe le mani, o un globo che ti permetta di usare un pugnale o una spada come arma.\n\nAffrontare l'infernale è stata una grande impresa da parte tua, e questa ricompensa ti si addice. Ti auguro altri successi nelle arti, {name}.", 0x2893fd72, 0xa83dbe16, 0x7c553bb6, nil, 0xa7b51784, "...m." },
  [4976] = { "La restituzione della sfera purificata", "Riporta la ⟦Cleansed Infernal Orb=Sfera Infernale Purificata⟧ a Menara Voidrender, nelle ⟦Barrens=Savane⟧.", "Riporta la sfera purificata a Menara, a ⟦Ratchet=Porto Paranco⟧, {name}. Portale i miei saluti e sta' attent<o/a>. Spero davvero che saprai resistere alla tentazione e alla corruzione che di certo incontrerai lungo il tuo cammino.\n\nBuona fortuna.", "Come procede la ricerca di Tabetha e del globo, {name}?\n\nTabetha si è dimostrata più che utile nelle questioni arcane. Di certo non avrà problemi ad aiutarti, se riuscirai a trovarla.", "Ben fatto, {name}. Questa andrà benissimo.\n\nNon ti resta che decidere quale demone vuoi che imprigioni nella sfera purificata. Fallo, e avrai un magnifico nuovo oggetto da impugnare.", 0xa1f2e73c, 0x4d497ee2, 0x7b21dd71, 0x3e294480, 0x638e5fcd, "....." },
})
